<script setup lang="ts">
import { computed, onMounted, ref } from "vue";
import { Plus, RadioTower, Search } from "lucide-vue-next";
import EmptyState from "../components/EmptyState.vue";
import StatusTag from "../components/StatusTag.vue";
import { api } from "../services/api";

type Options={regions:string[];room_groups:string[];rooms:string[];brands:string[];models:string[]};
const REGION_LABELS:Record<string,string>={chengbei:"城北",chengdong:"城东",chengnan:"城南",chengxi:"城西",gaochun:"高淳",jiangning:"江宁",lishui:"溧水",liuhe:"六合",pukou:"浦口",qixia:"栖霞",yuhua:"雨花",nanjing:"南京"};
const rows=ref<any[]>([]),options=ref<Options>({regions:[],room_groups:[],rooms:[],brands:[],models:[]}),total=ref(0),page=ref(1),size=ref(20),loading=ref(false),saving=ref(false),error=ref(""),message=ref(""),formOpen=ref(false),editingId=ref<number|null>(null);
const filters=ref({keyword:"",region:"",room_group:"",room:"",device_model:"",active:"1"});
const form=ref(emptyForm());
function emptyForm(){return {name:"",region:"",room_group:"",room:"",brand:"",device_model:"",primary_ip:"",backup_ip:"",community:"",external_database:"",external_id:"",is_active:true};}
function regionLabel(value:string){return REGION_LABELS[value]||value||"未分区域";}
const pages=computed(()=>Math.max(1,Math.ceil(total.value/size.value)));
function query(){const p=new URLSearchParams({page:String(page.value),size:String(size.value)});for(const [key,value] of Object.entries(filters.value))if(value)p.set(key,value);return p.toString();}
async function load(){loading.value=true;error.value="";try{const data=await api<any>(`/cmts/devices?${query()}`);rows.value=data.items||[];total.value=data.total||0;}catch(e){error.value=e instanceof Error?e.message:"CMTS 设备加载失败";}finally{loading.value=false;}}
async function loadOptions(){try{options.value=await api<Options>("/cmts/device-options");}catch(e){error.value=e instanceof Error?e.message:"设备选项加载失败";}}
function search(){page.value=1;load();}function reset(){filters.value={keyword:"",region:"",room_group:"",room:"",device_model:"",active:"1"};search();}function goto(n:number){page.value=Math.max(1,Math.min(pages.value,n));load();}
function openCreate(){editingId.value=null;form.value=emptyForm();formOpen.value=true;}function openEdit(row:any){editingId.value=row.cmts_device_id;form.value={...emptyForm(),...row,is_active:!!row.is_active,external_id:row.external_id||"",community:""};formOpen.value=true;}
async function save(){saving.value=true;error.value="";try{const url=editingId.value?`/cmts/devices/${editingId.value}`:"/cmts/devices";await api(url,{method:editingId.value?"PUT":"POST",body:JSON.stringify(form.value)});message.value=editingId.value?"CMTS 设备已更新":"CMTS 设备已新增";formOpen.value=false;await Promise.all([load(),loadOptions()]);}catch(e){error.value=e instanceof Error?e.message:"CMTS 设备保存失败";}finally{saving.value=false;}}
onMounted(()=>Promise.all([load(),loadOptions()]));
</script>

<template><div class="manage-page"><section class="manage-hero card card-pad"><div><div class="eyebrow">HFC 设备基础档案</div><h1>CMTS 设备管理</h1><p>维护 CMTS 的区域、机房、型号和访问配置；MAC 查询会关联这些设备信息。</p></div><button class="btn btn-primary" @click="openCreate"><Plus :size="17"/>新增 CMTS</button></section><div v-if="error" class="quality-message error">{{error}}</div><div v-if="message" class="quality-message success">{{message}}</div><section class="card manage-filter"><div class="manage-filter-grid"><label class="filter-search"><Search :size="15"/><input v-model="filters.keyword" placeholder="设备名称 / 主备 IP" @keydown.enter="search"/></label><select v-model="filters.region" class="select"><option value="">全部区域</option><option v-for="v in options.regions" :key="v" :value="v">{{regionLabel(v)}}</option></select><select v-model="filters.room_group" class="select"><option value="">全部机房组</option><option v-for="v in options.room_groups" :key="v">{{v}}</option></select><select v-model="filters.room" class="select"><option value="">全部机房</option><option v-for="v in options.rooms" :key="v">{{v}}</option></select><select v-model="filters.device_model" class="select"><option value="">全部型号</option><option v-for="v in options.models" :key="v">{{v}}</option></select><select v-model="filters.active" class="select"><option value="">全部状态</option><option value="1">在用</option><option value="0">停用</option></select><div class="manage-filter-actions"><button class="btn btn-primary" @click="search">查询</button><button class="btn btn-secondary" @click="reset">重置</button></div></div></section><section class="card table-card manage-table-card" :class="{loading}"><div class="table-head"><div><h2>CMTS 设备档案</h2><p>共 {{total}} 台，可查看已采集 CM 数量和最近采集时间。</p></div><select v-model.number="size" class="select tiny-select" @change="goto(1)"><option :value="20">20 条/页</option><option :value="50">50 条/页</option><option :value="100">100 条/页</option></select></div><EmptyState v-if="!loading&&!rows.length" title="暂无 CMTS 设备" description="请调整筛选条件或新增 CMTS。"/><div v-else class="table-wrap"><table class="data-table manage-data-table"><thead><tr><th>CMTS 设备</th><th>区域 / 机房</th><th>品牌 / 型号</th><th>主备 IP</th><th>CM 数量</th><th>最近采集</th><th>状态</th><th>操作</th></tr></thead><tbody><tr v-for="row in rows" :key="row.cmts_device_id"><td><strong>{{row.name}}</strong><div class="muted">设备 ID {{row.cmts_device_id}}</div></td><td>{{regionLabel(row.region)}} / {{row.room_group||'-'}}<div class="muted">{{row.room||'未分机房'}}</div></td><td>{{row.brand||'-'}}<div class="muted">{{row.device_model||'-'}}</div></td><td>{{row.primary_ip||'-'}}<div class="muted">备用 {{row.backup_ip||'-'}}</div></td><td><strong>{{row.cm_count||0}}</strong></td><td>{{row.last_query_time||'-'}}</td><td><StatusTag :value="row.is_active?'在用':'停用'"/><div class="muted">团体号 {{row.community_configured?'已配置':'未配置'}}</div></td><td><button class="outline-action" @click="openEdit(row)">编辑</button></td></tr></tbody></table></div><div v-if="total" class="pagination modern-pagination"><button class="btn btn-secondary" :disabled="page<=1" @click="goto(page-1)">‹</button><span>第 {{page}} / {{pages}} 页</span><button class="btn btn-secondary" :disabled="page>=pages" @click="goto(page+1)">›</button></div></section><div v-if="formOpen" class="quality-detail-mask" @click.self="formOpen=false"><section class="quality-detail-panel device-form-panel card"><header class="detail-panel-head"><div><span>{{editingId?'编辑 CMTS':'新增 CMTS'}}</span><h2>{{form.name||'CMTS 设备信息'}}</h2><p>编辑时留空 SNMP 团体号不会覆盖原有配置。</p></div><button class="round-icon-btn" @click="formOpen=false">×</button></header><div class="device-form-grid"><div class="field"><label>设备名称 *</label><input v-model="form.name" class="input"/></div><div class="field"><label>主 IP *</label><input v-model="form.primary_ip" class="input" placeholder="192.168.x.x"/></div><div class="field"><label>SNMP 团体号</label><input v-model="form.community" class="input" type="password"/></div><div class="field"><label>区域</label><select v-model="form.region" class="select"><option value="">未分区域</option><option v-for="v in options.regions" :key="v" :value="v">{{regionLabel(v)}}</option></select></div><div class="field"><label>机房组</label><input v-model="form.room_group" class="input" list="cmts-room-groups"/></div><div class="field"><label>机房</label><input v-model="form.room" class="input" list="cmts-rooms"/></div><div class="field"><label>品牌</label><input v-model="form.brand" class="input" list="cmts-brands"/></div><div class="field"><label>型号</label><input v-model="form.device_model" class="input" list="cmts-models"/></div><div class="field"><label>备用 IP</label><input v-model="form.backup_ip" class="input"/></div><div class="field"><label>外部数据源</label><input v-model="form.external_database" class="input"/></div><div class="field"><label>外部设备 ID</label><input v-model="form.external_id" class="input"/></div><label class="perf-switch"><input v-model="form.is_active" type="checkbox"/>加入采集清单</label></div><datalist id="cmts-room-groups"><option v-for="v in options.room_groups" :key="v" :value="v"/></datalist><datalist id="cmts-rooms"><option v-for="v in options.rooms" :key="v" :value="v"/></datalist><datalist id="cmts-brands"><option v-for="v in options.brands" :key="v" :value="v"/></datalist><datalist id="cmts-models"><option v-for="v in options.models" :key="v" :value="v"/></datalist><footer class="device-form-actions"><button class="btn btn-secondary" @click="formOpen=false">取消</button><button class="btn btn-primary" :disabled="saving" @click="save">{{saving?'保存中…':'保存 CMTS'}}</button></footer></section></div></div></template>
